import React, { FocusEvent, HTMLProps, useImperativeHandle, useRef, useState } from 'react';
import InputWrapper, { InputWrapperProps } from '../InputWrapper';
import { StyledInput, InputContainer, InputCharacter } from './Input.styles';

export interface InputProps
  extends Omit<HTMLProps<HTMLInputElement>, 'children' | 'size' | 'css'>,
    Omit<InputWrapperProps, 'children' | 'counter' | 'maxCounter'> {
  size?: 'small' | 'large';
  width?: string | number;
  sufix?: string;
  prefix?: string;
}

export const Input = React.forwardRef(
  (
    {
      characterCounter,
      hint,
      label,
      legend,
      required,
      optionalText = '(Optional)',
      hasError,
      disabled = false,
      errorText,
      labelProps,
      value: valueFromProps,
      onChange: onChangeFromProps,
      defaultValue,
      size = 'large',
      placeholder = 'Placeholder text',
      id,
      width,
      sufix,
      prefix,
      ...otherProps
    }: InputProps,
    forwardedRef: React.ForwardedRef<HTMLInputElement>
  ): JSX.Element => {
    const isControlled = valueFromProps !== undefined;
    const hasDefaultvalue = defaultValue !== undefined;
    const [value, setValue] = useState(() => (hasDefaultvalue ? defaultValue?.toString() : ''));
    const [focused, setFocused] = useState(false);
    const mappedValue = isControlled ? valueFromProps?.toString() : value;

    const innerRef = useRef<HTMLInputElement>(null);
    useImperativeHandle(forwardedRef, () => innerRef?.current as HTMLInputElement);

    const mappedPlaceholder = !label && !required ? `${placeholder} ${optionalText}` : placeholder;

    const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (onChangeFromProps && typeof onChangeFromProps === 'function') {
        onChangeFromProps(e);
        if (!isControlled) setValue(e.target.value);
        return;
      }
      setValue(e.target.value);
    };

    return (
      <InputWrapper
        labelProps={{ ...labelProps, htmlFor: id }}
        label={label}
        hint={hint}
        legend={legend}
        hasError={hasError}
        disabled={disabled}
        required={required}
        errorText={errorText}
        optionalText={optionalText}
        characterCounter={characterCounter}
        counter={mappedValue?.length}
        maxCounter={otherProps.maxLength}
        width={width}
      >
        <InputContainer
          disabled={disabled}
          hasError={hasError}
          focused={focused}
          hasPrefixOrSufix={!!prefix || !!sufix}
        >
          <InputCharacter prefix={!!prefix} size={size}>
            {prefix}
          </InputCharacter>
          <StyledInput
            {...otherProps}
            sufix={!!sufix}
            prefix={!!prefix}
            id={id}
            ref={innerRef}
            value={mappedValue}
            onChange={onChange}
            disabled={disabled}
            size={size}
            placeholder={mappedPlaceholder?.trim()}
            onFocus={(e: FocusEvent<HTMLInputElement>) => {
              if (!hasError) setFocused(true);
              otherProps?.onFocus?.(e);
            }}
            onBlur={(e: FocusEvent<HTMLInputElement>) => {
              setFocused(false);
              otherProps?.onBlur?.(e);
            }}
          />
          <InputCharacter sufix={!!sufix} size={size}>
            {sufix}
          </InputCharacter>
        </InputContainer>
      </InputWrapper>
    );
  }
);

export default Input;
